sections.body:
下面保存为 gesture-gate.mjs，用 node gesture-gate.mjs 运行。t 是采集帧时的单调时间，单位毫秒；摄像头适配层先取单手的最高得分类别，无手时传空字符串和 0。代码不包含模型推理、摄像头或技能冷却。

```js
/**
 * @Author liliwei
 * @Date 2026-10-24
 * @LastEditors liliwei
 * @LastEditTime 2026-10-24
 * @description 原创教学示例：将单手识别样本转为一次施法意图。
 */
/** @typedef {{t:number, label:string, score:number}} GestureSample */

/**
 * 创建独立门控器；200ms 稳定期、150ms 最大样本间隔仅为练习参数。
 * @returns {(sample: GestureSample) => boolean} 本次是否发出施法意图。
 */
export function createGestureGate() {
  let last = -Infinity, current = '', since = 0, armed = false;
  /**
   * 接受按采集时间排序的样本；重复与倒序样本忽略。
   * @param {GestureSample} sample t 为同一单调时钟下的毫秒值。
   * @returns {boolean} true 只表示输入意图，扣费与冷却由游戏判断。
   */
  return function accept({ t, label, score }) {
    if (!Number.isFinite(t) || t < 0 || typeof label !== 'string' ||
        !Number.isFinite(score) || score < 0 || score > 1)
      throw new Error('Invalid gesture sample');
    if (t <= last) return false;
    if (t - last > 150) { armed = false; current = ''; }
    last = t;
    const valid = score >= 0.8 &&
      (label === 'Open_Palm' || label === 'Closed_Fist');
    if (!valid) { armed = false; current = ''; return false; }
    if (label !== current) { current = label; since = t; }
    if (label === 'Open_Palm' && t - since >= 200) armed = true;
    if (label === 'Closed_Fist' && armed && t - since >= 200) {
      armed = false;
      return true;
    }
    return false;
  };
}

const gate = createGestureGate();
const trace = [
  [0, 'Open_Palm'], [100, 'Open_Palm'], [200, 'Open_Palm'],
  [300, 'Closed_Fist'], [400, 'Closed_Fist'], [500, 'Closed_Fist'],
  [600, 'Closed_Fist'], [700, 'Closed_Fist']
];
const casts = trace.filter(([t, label]) => gate({ t, label, score: 0.9 }));
console.log(casts.map(([t]) => t)); // [500]，单位 ms
```

正文代码原样提取后，在 Node.js 22.16.0 实跑：八个样本只在 t=500 发出一次意图；握拳五个样本若逐帧直接施法会发出五次。张掌在 t=200 完成准备，握拳从 t=300 到 500 达到稳定期；这 200ms 是规则主动加入的等待，不是设备推理延迟。

| 人工构造的轨迹 | 门控发出次数 |
| --- | --- |
| 正文张掌后握拳并保持 | 1 |
| 再接张掌 800/900/1000，握拳 1100/1200/1300 | 2，分别在 500 和 1300 |
| 从开始就一直握拳 | 0 |
| 准备后，握拳中途出现低分或无手，未重新张掌 | 0 |
| 准备后采样中断超过 150ms，再直接握拳 | 0 |

另检查了分数恰好 0.8、稳定时间恰好 200ms、间隔恰好 150ms、重复和倒序样本、非法分数及时间。检查证明状态机按这份合同工作，不证明模型识别率或玩家体验。低分立即取消准备比较保守，可能增加漏触；若以后增加容错，应保留故障轨迹重新比较。
